import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.C0kwIWkz.js";const m=JSON.parse('{"title":"OME-Zarr","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/docs-changelog-0-6-0/data/ome-zarr.html"}],["meta",{"property":"og:title","content":"OME-Zarr | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/docs-changelog-0-6-0/data/ome-zarr.html"}],["meta",{"name":"twitter:title","content":"OME-Zarr | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"data/ome-zarr.md","filePath":"data/ome-zarr.md"}'),s={name:"data/ome-zarr.md"};function i(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ome-zarr" tabindex="-1">OME-Zarr <a class="header-anchor" href="#ome-zarr" aria-label="Permalink to &quot;OME-Zarr&quot;">​</a></h1><p>Kiln streams multiscale <a href="https://ngff.openmicroscopy.org/" target="_blank" rel="noreferrer">OME-Zarr</a> directly over HTTP, with no conversion, and is listed in the <a href="https://ngff.openmicroscopy.org/resources/tools/index.html" target="_blank" rel="noreferrer">OME-NGFF tools registry</a>. For raw volumes, see the <a href="/preview/docs-changelog-0-6-0/data/sharded-binary.html">sharded binary format</a>.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> viewer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KilnViewer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(canvas, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://example.com/data/scan.ome.zarr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Any URL that doesn&#39;t serve a sharded binary <code>volume.json</code> is read as OME-Zarr, so URLs without <code>.zarr</code> (such as webKnossos layers) work too. Public test data: the <a href="https://registry.opendata.aws/ome-zarr-open-scivis/" target="_blank" rel="noreferrer">OME-Zarr Open SciVis Datasets</a>, e.g. <code>https://ome-zarr-scivis.s3.us-east-1.amazonaws.com/v0.5/96x2/beechnut.ome.zarr</code>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>NGFF v0.4 or v0.5</strong> with <code>multiscales</code> metadata</li><li><strong>Spatial axes last:</strong> <code>z, y, x</code> as usual, or <code>x, y, z</code> as written by <a href="https://webknossos.org" target="_blank" rel="noreferrer">webKnossos</a>. Kiln reads the order from <code>axes</code> and reads chunks through their strides, so nothing is transposed</li><li><strong>Channels:</strong> any 1–4 of a <code>c</code> axis at once (see <a href="/preview/docs-changelog-0-6-0/rendering/multichannel.html">Multichannel</a>); <strong>time:</strong> one timepoint at a time</li><li><strong>Labels:</strong> label images in the <code>labels</code> group, or at other URLs, are shown as layers over the volume (see <a href="/preview/docs-changelog-0-6-0/rendering/labels.html">Labels</a>)</li><li><strong>Data types:</strong> <code>uint8</code>, <code>uint16</code>, <code>int16</code>, <code>float32</code>; <code>float64</code> is read as <code>float32</code>. Others, such as <code>int8</code> or <code>uint32</code>, are rejected with a reason</li><li><strong>Levels:</strong> each multiscale level is a LOD. Kiln reads each level&#39;s own size and per-axis downsampling (1× or 2×). If the levels don&#39;t fit that model, for example a level a few slices short of half its parent, it falls back to a uniform 2:1 model and logs why. <code>?pyramid=native</code> or <code>?pyramid=legacy</code> forces either</li><li><strong>Spacing</strong> from <code>coordinateTransformations</code>; <strong>windows</strong> from OMERO metadata when present</li></ul><h2 id="storage-on-the-gpu" tabindex="-1">Storage on the GPU <a class="header-anchor" href="#storage-on-the-gpu" aria-label="Permalink to &quot;Storage on the GPU&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Atlas format</th><th>Normalised by</th></tr></thead><tbody><tr><td><code>uint8</code></td><td><code>r8unorm</code></td><td>type range</td></tr><tr><td><code>uint16</code></td><td><code>r16unorm</code> (bit-exact) where the GPU <a href="/preview/docs-changelog-0-6-0/reference/webgpu.html">supports it</a>, else <code>r16float</code> (exact up to 4096, i.e. 12-bit data)</td><td>type range</td></tr><tr><td><code>int16</code>, <code>float32</code></td><td><code>r16float</code> (half precision)</td><td>data range: OMERO window, else the 0.1–99.9th percentile of the coarsest level</td></tr></tbody></table><h2 id="layout-tips" tabindex="-1">Layout tips <a class="header-anchor" href="#layout-tips" aria-label="Permalink to &quot;Layout tips&quot;">​</a></h2><p>Two properties of a dataset decide how soon a full coarse image appears:</p><ul><li><strong>Downsample every axis.</strong> If the levels halve X and Y but keep Z, the coarsest level can still be hundreds of megabytes: a 1920×1920×752 stack with four channels has a 240×240×752 coarsest level of about 270 MB compressed. Add a level or two that also halve Z.</li><li><strong>Avoid whole-plane chunks.</strong> A brick can only be assembled once all chunks it overlaps have arrived; with one XY plane per chunk, that is most of a level. Cubic chunks (64³ or 128³) let bricks stream independently.</li></ul><p>Brick assembly (fetching chunks, decompressing, cutting 66³ bricks) runs in a worker pool. For Zarr v2 stores the metadata is read once and shared with the workers.</p>',12)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
